/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `Actividades_Evaluables` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `categoria_id` int(11) NOT NULL COMMENT 'La categoría a la que pertenece esta actividad',
  `nombre_actividad` varchar(255) NOT NULL COMMENT 'Ej: Tarea 1 - Resumen, Examen Parcial 2',
  `fecha_entrega` date DEFAULT NULL,
  `calificacion_maxima` decimal(5,2) NOT NULL DEFAULT 100.00 COMMENT 'La calificación máxima posible para esta actividad',
  `parcial` int(1) NOT NULL DEFAULT 1 COMMENT 'Parcial al que pertenece (1, 2, o 3)',
  PRIMARY KEY (`id`),
  KEY `categoria_id` (`categoria_id`),
  CONSTRAINT `actividades_evaluables_ibfk_1` FOREIGN KEY (`categoria_id`) REFERENCES `Categorias_Calificacion` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=638 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

