  `alumno_id` int(11) NOT NULL,
  `cargo_id` int(11) NOT NULL,
  `pago_id` int(11) DEFAULT NULL,
  `folio_asiento` int(11) NOT NULL,
  `estado_uso` enum('Disponible','Usado') DEFAULT 'Disponible',
  `fecha_emision` datetime DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `evento_id` (`evento_id`),
  KEY `alumno_id` (`alumno_id`),
  KEY `cargo_id` (`cargo_id`),
  CONSTRAINT `finanzas_boletos_ibfk_1` FOREIGN KEY (`evento_id`) REFERENCES `finanzas_eventos` (`id`),
  CONSTRAINT `finanzas_boletos_ibfk_2` FOREIGN KEY (`alumno_id`) REFERENCES `Usuarios` (`id`),
  CONSTRAINT `finanzas_boletos_ibfk_3` FOREIGN KEY (`cargo_id`) REFERENCES `finanzas_cargos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
