DROP TABLE IF EXISTS `finanzas_cargos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `finanzas_cargos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `alumno_id` int(11) NOT NULL,
  `concepto` varchar(255) NOT NULL,
  `monto_original` decimal(10,2) NOT NULL DEFAULT 0.00,
  `monto_pagado` decimal(10,2) DEFAULT 0.00,
  `beca_aplicada` decimal(10,2) NOT NULL DEFAULT 0.00,
  `recargos` decimal(10,2) NOT NULL DEFAULT 0.00,
  `total` decimal(10,2) GENERATED ALWAYS AS (`monto_original` + `recargos`) STORED,
  `estado` varchar(50) DEFAULT 'Pago Pendiente',
  `fecha_vencimiento` date DEFAULT NULL,
  `fecha_pago` datetime DEFAULT NULL,
  `metodo_pago` varchar(50) DEFAULT NULL,
  `referencia_pago` varchar(255) DEFAULT NULL,
  `comprobante_url` varchar(255) DEFAULT NULL,
  `notas_ajuste` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `evento_id` int(11) DEFAULT NULL,
  `cantidad_boletos` int(11) DEFAULT 1,
  `cuenta_receptora_id` int(11) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `alumno_id` (`alumno_id`),
  CONSTRAINT `finanzas_cargos_ibfk_1` FOREIGN KEY (`alumno_id`) REFERENCES `Usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
